let authToken='',cloudMode=false,authRequired=false,pollTimer=null,syncTimer=null;let token='',fields={},derived=[],S=null,A='',page='dashboard',theme=localStorage.getItem('dp-theme')||'light',edit=null,formDraft=null,columns=null,custom=null,dirtyColumns=false,search='',filter='All',sort='recent',pg=1,grid=false,selected=new Set(),modalFn=null,busy=false,refreshing=false;
const navs=[['WORKSPACE',[['dashboard','Dashboard','dashboard'],['add','Add product','plus'],['products','My products','box'],['research','Competitor research','search'],['calculator','Profit calculator','calc']]],['AUTOMATION',[['monitor','Product monitoring','activity'],['sheets','Spreadsheets','sheet'],['builder','Sheet builder','sheet'],['fees','Fee settings','calc']]],['MANAGEMENT',[['analytics','Analytics','chart'],['notifications','Notifications','bell'],['trash','Recycle bin','trash'],['settings','Settings','settings']]]];
const navname=()=>navs.flatMap(x=>x[1]).find(x=>x[0]===page)?.[1]||'Dashboard';
async function api(path,data){let headers={};if(authToken)headers.Authorization='Bearer '+authToken;if(data){headers['Content-Type']='application/json';headers['X-DropPilot-Token']=token}let res=await fetch('/api/'+path,{method:data?'POST':'GET',headers,body:data?JSON.stringify({...data,account:A}):undefined,cache:'no-store'});let out=await res.json();if(res.status===401&&authRequired){showLogin('Your session expired. Please sign in again.');throw Error('Sign in required')}if(!res.ok)throw Error(out.error||'Request failed');return out}
function showLogin(message=''){authToken='';S=null;clearInterval(pollTimer);clearInterval(syncTimer);$('#modal-root').innerHTML='';$('#toasts').innerHTML='';document.documentElement.classList.toggle('dark',theme==='dark');$('#app').innerHTML=`<main class="login-screen"><section class="login-intro"><div class="login-brand"><img src="/favicon.svg" alt=""> DropPilot</div><div><span class="login-kicker">RESEARCH WORKSPACE</span><h1>Make every product<br>count.</h1><p>Manage your product research, pricing and spreadsheets in one private workspace.</p><div class="login-points"><span>${I('check')} Product intelligence</span><span>${I('check')} Spreadsheet automation</span><span>${I('check')} Private access</span></div></div><small>DropPilot · Personal workspace</small></section><section class="login-panel"><div class="login-card"><div class="login-lock">${I('user')}</div><h2>Welcome back</h2><p>Sign in to your DropPilot workspace.</p><form id="login-form" class="stack"><label>Email address<input type="email" name="email" autocomplete="username" placeholder="Enter your email" required></label><label>Password<div class="login-password"><input type="password" name="password" autocomplete="current-password" placeholder="Enter your password" required><button id="show-password" type="button" class="ghost">Show</button></div></label><div id="login-error" role="alert" class="login-error">${esc(message)}</div><button class="primary login-submit" type="submit">Sign in ${I('right')}</button></form><small>Private access · Sign-in required for each new tab.</small></div></section></main>`;let f=$('#login-form');$('#show-password').onclick=()=>{let p=f.elements.password;p.type=p.type==='password'?'text':'password';$('#show-password').textContent=p.type==='password'?'Show':'Hide'};f.onsubmit=async e=>{e.preventDefault();let b=f.querySelector('[type=submit]');b.disabled=true;b.textContent='Signing in…';$('#login-error').textContent='';try{let r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:f.elements.email.value,password:f.elements.password.value}),cache:'no-store'});let v=await r.json();if(!r.ok)throw Error(v.error||'Unable to sign in');authToken=v.token;f.elements.password.value='';await bootWorkspace()}catch(e){if($('#login-error'))$('#login-error').textContent=e.message;else showLogin(e.message)}finally{b.disabled=false;b.textContent='Sign in'}}}
async function logout(){try{await api('auth/logout',{})}catch(e){}finally{showLogin('You have been signed out.')}}
async function exportCsv(){let r=await fetch('/api/export?account='+encodeURIComponent(A),{headers:authToken?{Authorization:'Bearer '+authToken}:{},cache:'no-store'});if(r.status===401){showLogin('Please sign in again.');return}if(!r.ok)throw Error('Export failed');let u=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=u;a.download='droppilot-products.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function refresh(renderNow=true){if(refreshing)return;refreshing=true;try{S=await api('state?account='+encodeURIComponent(A));if(renderNow)render()}finally{refreshing=false}}
function toast(title,detail='',type='success'){let e=document.createElement('div');e.className='toast '+type;e.innerHTML=`<span class="${type==='error'?'bad':type==='info'?'warn':'good'}">${I(type==='error'?'alert':type==='info'?'info':'check')}</span><div><b>${esc(title)}</b><p>${esc(detail)}</p></div><button class="ghost" aria-label="Dismiss">${I('close')}</button>`;e.querySelector('button').onclick=()=>e.remove();$('#toasts').append(e);setTimeout(()=>e.remove(),5500)}
function modal(title,body,fn=null,opts={}){modalFn=fn;$('#modal-root').innerHTML=`<div class="modalback"><section class="modal ${opts.wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${esc(title)}</h2>${btn('','close-modal','close','ghost icon','aria-label="Close"')}</div>${body}<div class="modalfoot">${btn(fn?'Cancel':'Close','close-modal','','')}${fn?btn(opts.label||'Confirm','confirm','',opts.danger?'danger':'primary'):''}</div></section></div>`;$('.modal input')?.focus()}
function closeModal(){$('#modal-root').innerHTML='';modalFn=null}
function confirm(title,detail,fn,danger=false,label='Confirm'){modal(title,`<div class="modalmark ${danger?'danger':''}">${I(danger?'trash':'check')}</div><p>${esc(detail)}</p>`,fn,{danger,label})}
function go(p){if(p==='builder'){columns=structuredClone(S.account.columns);custom=structuredClone(S.account.custom);dirtyColumns=false}if(p==='add'){edit=null;formDraft=null}page=p;pg=1;selected.clear();render();window.scrollTo(0,0)}
function head(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">DropPilot / ${esc(navname())}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}
function banner(t){return `<div class="banner">${I('info')}<span>${esc(t)}</span></div>`}
function empty(t='No products yet',d='Add your first product to get started.'){return `<div class="empty">${I('box')}<h3>${esc(t)}</h3><p>${esc(d)}</p></div>`}
function metric(title,value,foot,icon='box',cl=''){return `<div class="card metric"><div class="metric-top">${esc(title)}<span class="metric-icon">${I(icon)}</span></div><div class="metric-value ${cl}">${esc(value)}</div><div class="metric-foot">${esc(foot)}</div></div>`}
function stats(){let p=S.products.filter(x=>x.status!=='Archived'),profits=p.filter(x=>x.status==='Published'),sum=profits.reduce((a,b)=>a+b.profit,0),roi=p.filter(x=>x.roi!=null);return {p,profits,sum,roi:roi.length?roi.reduce((a,b)=>a+b.roi,0)/roi.length:null,stock:p.filter(x=>x.stock==='In stock').length,out:p.filter(x=>x.stock==='Out of stock').length,unknown:p.filter(x=>x.stock==='Unknown').length}}
function events(es){return es.length?es.map(e=>`<div class="event"><div class="eventico ${e.kind==='warning'?'warn':'good'}">${I(e.kind==='warning'?'alert':e.kind==='success'?'check':'info')}</div><div><b>${esc(e.title)}</b><p>${esc(e.detail)}</p></div><time>${esc(date(e.created))}</time></div>`).join(''):empty('No activity','Changes and alerts will appear here.')}
function productCell(p){return `<div class="productcell"><div class="producticon">${I('box')}</div><div><b>${esc(p.title)}</b><small>${esc(p.asin||p.category||'Product research')}</small></div></div>`}
function smallTable(ps){return `<div class="tablewrap"><table class="table"><thead><tr><th>Product</th><th>Source cost</th><th>Sell price</th><th>Est. profit</th><th>Stock</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td>${productCell(p)}</td><td>${money(p.total_cost)}</td><td>${money(p.selling_price)}</td><td class="${p.profit>=0?'good':'bad'} number">${money(p.profit)}</td><td>${tag(p.stock)}</td><td>${btn('','edit:'+p.id,'right','ghost icon','aria-label="Edit product"')}</td></tr>`).join('')||`<tr><td colspan="6">${empty()}</td></tr>`}</tbody></table></div>`}
function dashboard(){let t=stats(),max=Math.max(1,...t.p.map(x=>x.profit)),a=t.p.length?t.stock/t.p.length*100:0,b=t.p.length?t.out/t.p.length*100:0;return head('Business overview','Your research, margins and inventory signals in one place.',btn('Import CSV','csv','download')+btn('Add product','go:add','plus','primary'))+(S.account.demo?banner('Demo workspace · sample products and estimates, not live Amazon or eBay data. Create a new workspace before connecting a real sheet.'):'')+`<div class="cards">${metric('Total products',String(t.p.length),`${t.profits.length} published to workspace`,'box')}${metric('Estimated profit / unit',money(t.sum),'Sum of per-unit profit for published products','wallet',t.sum<0?'bad':'')}${metric('Average ROI',pct(t.roi),'Across products with known source costs','chart')}${metric('Out of stock',String(t.out),`${t.unknown} availability unknown`,'activity',t.out?'bad':'')}</div><div class="grid2"><div class="card"><div class="cardhead"><div><h2>Top product opportunities</h2><p class="muted">Estimated profit per unit</p></div>${btn('View analytics','go:analytics','right','small')}</div><div class="bars">${[...t.p].sort((a,b)=>b.profit-a.profit).slice(0,5).map(p=>`<div class="baritem"><span title="${esc(p.title)}">${esc(p.title)}</span><div class="track"><div class="fill" style="width:${Math.max(0,p.profit/max*100)}%"></div></div><b class="number ${p.profit<0?'bad':''}">${money(p.profit)}</b></div>`).join('')||empty()}</div></div><div class="card"><div class="cardhead"><div><h2>Stock overview</h2><p class="muted">Last recorded availability</p></div>${btn('Monitor','go:monitor','','small')}</div><div class="donutrow"><div class="donut" style="background:conic-gradient(#548568 0 ${a}%,#c46b58 ${a}% ${a+b}%,#c8c4b8 ${a+b}% 100%)"><div class="donut-inner"><b>${t.p.length}</b><small>Products</small></div></div><div class="legend"><div><i style="background:#548568"></i>In stock <b>${t.stock}</b></div><div><i style="background:#c46b58"></i>Out of stock <b>${t.out}</b></div><div><i style="background:#c8c4b8"></i>Unknown <b>${t.unknown}</b></div></div></div></div></div><div class="card" style="margin-bottom:18px"><div class="cardhead"><h2>Recent products</h2>${btn('View all','go:products','right','small')}</div>${smallTable(t.p.slice(0,5))}</div><div class="card"><div class="cardhead"><h2>Recent activity</h2>${btn('See all','go:notifications','right','small')}</div>${events(S.events.slice(0,4))}</div>`}
function filtered(){let x=S.products.filter(p=>(filter==='All'||p.stock===filter||p.status===filter||(filter==='Low profit'&&p.profit<S.account.settings.target_profit))&&(!search||[p.title,p.seo_title,p.keyword,p.asin,p.amazon_url,p.ebay_url].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase()))));if(sort==='profit')x.sort((a,b)=>b.profit-a.profit);if(sort==='roi')x.sort((a,b)=>(b.roi??-Infinity)-(a.roi??-Infinity));if(sort==='title')x.sort((a,b)=>a.title.localeCompare(b.title));return x}
function productsPage(){let list=filtered(),max=Math.max(1,Math.ceil(list.length/25));pg=Math.min(pg,max);let rows=list.slice((pg-1)*25,pg*25);return head('My products','Edit, compare, publish and organize your research.',btn('Export CSV','export','download')+btn('Add product','go:add','plus','primary'))+`<div class="card"><div class="toolrow"><input id="search-products" placeholder="Search products, ASIN, keyword…" value="${esc(search)}" aria-label="Search products"><select id="product-filter">${['All','In stock','Out of stock','Unknown','Draft','Published','Archived','Low profit'].map(x=>`<option ${x===filter?'selected':''}>${x}</option>`).join('')}</select><select id="product-sort">${[['recent','Recent'],['profit','Highest profit'],['roi','Highest ROI'],['title','Title A–Z']].map(([v,l])=>`<option value="${v}" ${v===sort?'selected':''}>${l}</option>`).join('')}</select><span class="spacer"></span>${btn(grid?'Table view':'Grid view','view',grid?'sheet':'dashboard','small')}${btn('Import CSV','csv','download','small')}</div><div class="row" style="margin-bottom:12px"><span class="muted">${list.length} products · ${selected.size} selected</span><span class="spacer"></span>${selected.size?btn('Publish selected','bulk:Published','','small')+btn('Archive','bulk:Archived','','small')+btn('Delete','bulk:delete','trash','small'):''}</div><div id="product-results">${grid?`<div class="productgrid">${rows.map(p=>`<div class="card"><div class="row between"><input type="checkbox" data-select="${p.id}" ${selected.has(p.id)?'checked':''}>${tag(p.status)}</div>${productCell(p)}<div class="summary"><div class="line">Cost <b>${money(p.total_cost)}</b></div><div class="line">Selling <b>${money(p.selling_price)}</b></div><div class="line">Profit <b>${money(p.profit)}</b></div><div class="line">ROI <b>${pct(p.roi)}</b></div></div><div class="row between" style="margin-top:10px">${tag(p.stock)}${btn('Edit','edit:'+p.id,'edit','small')}</div></div>`).join('')||empty()}</div>`:`<div class="tablewrap flush"><table class="table"><thead><tr><th><input type="checkbox" id="select-page" aria-label="Select page" ${rows.length&&rows.every(p=>selected.has(p.id))?'checked':''}></th><th>Product</th><th>Cost</th><th>Selling</th><th>Profit</th><th>ROI</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td><input type="checkbox" data-select="${p.id}" ${selected.has(p.id)?'checked':''} aria-label="Select ${esc(p.title)}"></td><td>${productCell(p)}</td><td>${money(p.total_cost)}</td><td>${money(p.selling_price)}</td><td class="${p.profit>=0?'good':'bad'}">${money(p.profit)}</td><td>${pct(p.roi)}</td><td>${tag(p.stock)}</td><td>${tag(p.status)}</td><td>${btn('','edit:'+p.id,'edit','ghost icon','aria-label="Edit"')}${btn('','history:'+p.id,'history','ghost icon','aria-label="History"')}${btn('','delete:'+p.id,'trash','ghost icon','aria-label="Delete"')}</td></tr>`).join('')||`<tr><td colspan="9">${empty()}</td></tr>`}</tbody></table></div>`}</div><div class="pagination"><span>Page ${pg} of ${max}</span><div class="row">${btn('Previous','prev','left','small',pg===1?'disabled':'')}${btn('Next','next','right','small',pg===max?'disabled':'')}</div></div></div>`}
function optimize(s){let t=s.replace(/\b(free shipping|best seller|limited time|hot sale)\b/gi,' ').trim().split(/\s+/),o=[];for(let w of t){if(o.at(-1)?.toLowerCase()===w.toLowerCase())continue;if([...o,w].join(' ').length>80)break;o.push(w)}return o.join(' ')||s.slice(0,80)}
function calculation(p){let cost=num(p.source_price)+num(p.shipping)+num(p.tax)+num(p.other_cost),sell=num(p.selling_price),rate=(num(p.fee_pct)+num(p.ad_pct))/100,fixed=num(p.fixed_fee),fees=Math.round((sell*rate+fixed)*100+1e-8)/100,profit=sell-cost-fees;return {cost,sell,fees,profit,roi:cost?profit/cost*100:null,margin:sell?profit/sell*100:null,breakEven:rate<1?Math.ceil((cost+fixed)/(1-rate)*100)/100:null,target:rate<1?Math.ceil((cost+fixed+num(S.account.settings.target_profit))/(1-rate)*100)/100:null}}
function summary(p){let x=calculation(p);return `<div class="summary"><div class="line">Total source cost <b>${money(x.cost)}</b></div><div class="line">Selling price <b>${money(x.sell)}</b></div><div class="line">Estimated marketplace fees <b>${money(x.fees)}</b></div><div class="hr" style="margin:2px 0"></div><div class="muted">Estimated net profit / unit</div><div class="big ${x.profit>=0?'good':'bad'}">${money(x.profit)}</div><div class="line">ROI <b>${pct(x.roi)}</b></div><div class="line">Profit margin <b>${pct(x.margin)}</b></div><div class="line">Break-even price <b>${money(x.breakEven)}</b></div><div class="line">Target profit price <b>${money(x.target)}</b></div></div><p class="muted" style="font-size:11px;margin-top:12px">Estimate only. Buyer sales tax, category tiers, returns and other actual charges may differ.</p>`}
function defaultProduct(){let s=S.account.settings;return {title:'',amazon_url:'',ebay_url:'',source_price:0,shipping:0,tax:0,other_cost:0,selling_price:0,competitor_price:0,fee_pct:s.fee_pct,fixed_fee:s.fixed_fee,ad_pct:s.ad_pct,stock:'Unknown',status:'Draft',custom:{}}}
const nfield=(l,k,p)=>field(l,k,p[k]??'','number','min="0" step="0.01"');
function getForm(form){let f=new FormData(form),p={};for(let [k,v] of f.entries()){if(k.startsWith('custom_')){p.custom??={};p.custom[k]=v}else p[k]=v}return p}
function productForm(){let p=formDraft||edit||defaultProduct();return head(edit?'Edit product':'Add a product','Capture product details, review profitability, then publish to your sheet.',btn('Back to products','go:products','left')+(edit?btn('Price history','history:'+edit.id,'history'):''))+banner('Live marketplace fetching is not configured. Use the included browser capture extension or enter verified product details. Nothing is listed on eBay.')+`<div class="grid2"><form id="product-form" class="stack"><div class="card"><div class="cardhead"><h2>01 / Source product</h2><span class="tag">Amazon</span></div><div class="formgrid"><div class="span2">${field('Amazon product URL','amazon_url',p.amazon_url,'url','placeholder="https://www.amazon.com/dp/…"')}<div class="row" style="margin-top:8px">${btn('Extract ASIN','asin','link','small','type="button"')}${btn('Paste capture','paste','download','small','type="button"')}</div></div><div class="span2">${field('Product title','title',p.title,'text','placeholder="Enter product name"')}</div>${field('ASIN','asin',p.asin)}${sel('Availability','stock',p.stock,['Unknown','In stock','Out of stock'])}${nfield('Amazon price ($)','source_price',p)}${nfield('Shipping ($)','shipping',p)}${nfield('Source tax ($)','tax',p)}${nfield('Other costs ($)','other_cost',p)}${field('Source seller','source_seller',p.source_seller)}${field('Delivery estimate','delivery',p.delivery)}<div class="span2">${field('Image URL (optional)','image_url',p.image_url,'url')}</div><div class="span2">${field('Last checked (ISO date or note)','last_checked',p.last_checked)}${btn('Mark checked now','checked','check','small','type="button"')}</div></div></div><div class="card"><div class="cardhead"><h2>02 / Competitor & pricing</h2><span class="tag">eBay research</span></div><div class="formgrid"><div class="span2">${field('Competitor listing URL','ebay_url',p.ebay_url,'url')}</div>${nfield('Competitor total price ($)','competitor_price',p)}${nfield('Your selling price ($)','selling_price',p)}<div class="span2">${btn('Undercut by '+money(S.account.settings.undercut),'undercut','calc','small','type="button"')}</div>${nfield('Marketplace fee (%)','fee_pct',p)}${nfield('Fixed order fee ($)','fixed_fee',p)}${nfield('Ad fee (%)','ad_pct',p)}${field('Category','category',p.category)}${['sold','sold7','sold14','sold30'].map((k,i)=>field(['Total sold','Sold / 7 days','Sold / 14 days','Sold / 30 days'][i],k,p[k]??'','number','min="0" step="1"')).join('')}</div></div><div class="card"><div class="cardhead"><h2>03 / SEO & custom data</h2>${btn('Optimize title','optimize','spark','small','type="button"')}</div><div class="formgrid"><div class="span2">${field('SEO title (80 characters max)','seo_title',p.seo_title,'text','maxlength="80"')}<small class="muted" id="title-count">${String(p.seo_title||'').length} / 80 characters</small></div>${field('Primary keyword','keyword',p.keyword)}${sel('Workflow status','status',p.status,['Draft','Published','Archived'])}${S.account.custom.map(f=>field(f.heading,f.key,p.custom?.[f.key],f.type==='number'?'number':f.type==='url'?'url':'text',f.type==='number'?'min="0" step="any"':'')).join('')}${textArea('Notes','notes',p.notes)}</div></div></form><aside class="card stickycard"><div class="cardhead"><h2>Profit analysis</h2><span class="tag">Live estimate</span></div><div id="profit-summary">${summary(p)}</div><div class="hr"></div><div class="stack">${btn('Publish to sheet','save:Published','sheet','primary')}${btn('Save draft','save:Draft','check')}${edit?btn('Save current status','save:current','check','ghost'):''}</div><p class="muted" style="font-size:11px;margin-top:12px">Publishing saves locally and queues spreadsheet sync if automatic sync is enabled. Review connection status separately.</p></aside></div>`}
function calculator(){let p=formDraft||defaultProduct();return head('Profit calculator','Find the break-even selling price and target profit before you publish.')+`<div class="grid2"><div class="card"><h2>Pricing inputs</h2><div class="hr"></div><form id="calc-form" class="formgrid">${['source_price','shipping','tax','other_cost','competitor_price','selling_price','fee_pct','fixed_fee','ad_pct'].map(k=>nfield(fields[k],k,p)).join('')}</form><div class="row" style="margin-top:15px">${btn('Apply competitor undercut','calc-undercut','calc')}</div></div><div class="card"><h2>Estimated result</h2><div class="hr"></div><div id="profit-summary">${summary(p)}</div></div></div>`}
function builder(){let opts=Object.entries(fields).concat(custom.map(f=>[f.key,f.heading+' (custom)']));return head('Sheet builder','Choose exactly which data goes into each spreadsheet column.',btn('Add custom field','custom-field','plus')+btn('Save mapping','save-columns','check','primary'))+banner('Add a column by selecting an existing product field or create a custom field. Existing spreadsheets keep their physical column order; new headings append. Reordering here affects CSV exports and new sheets. Formula cells are preserved.')+`<div class="grid2 equal"><div class="card"><div class="cardhead"><h2>Column configuration</h2>${btn('Add column','add-column','plus','small')}</div><div class="muted" style="font-size:12px;margin-bottom:15px">Column · Spreadsheet heading · Data source</div><div id="col-list">${columns.map((col,i)=>`<div class="colrow" data-col="${i}"><span class="index">${String(i+1).padStart(2,'0')}</span><input value="${esc(col.heading)}" data-heading="${i}" aria-label="Column heading ${i+1}"><select data-source="${i}" aria-label="Column source ${i+1}">${opts.map(([k,v])=>`<option value="${esc(k)}" ${col.source===k?'selected':''}>${esc(v)}</option>`).join('')}</select><div class="actions">${btn('','col-up:'+i,'up','ghost icon',i===0?'disabled':'')}${btn('','col-down:'+i,'down','ghost icon',i===columns.length-1?'disabled':'')}${btn('','col-del:'+i,'trash','ghost icon')}</div></div>`).join('')}</div><div class="hr"></div><p class="muted">${columns.length} mapped columns · ${custom.length} custom fields. ${dirtyColumns?'Unsaved changes.':''}</p></div><div class="card stickycard"><h2>Live sheet preview</h2><p class="muted" style="font-size:12px;margin:7px 0 15px">Existing products automatically populate mapped data.</p><div class="sheetpreview"><table class="table"><thead><tr>${columns.map(c=>`<th>${esc(c.heading)}</th>`).join('')}</tr></thead><tbody>${S.products.slice(0,8).map(p=>`<tr>${columns.map(c=>`<td>${esc(c.source.startsWith('custom_')?p.custom?.[c.source]:p[c.source])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="hr"></div><h3>How it works</h3><p class="muted" style="font-size:12px">Example: add a column named “Source Seller” and choose Source Seller. On sync, DropPilot adds that header and writes the field for every linked or published product. Blank custom fields remain blank until you enter a value.</p></div></div>`}
function spreadsheets(){let c=S.account.connection||{};return head('Spreadsheet connections','Connect a Google spreadsheet or local Excel workbook to this workspace.',btn('Sync now','sync','sync','primary'))+banner('Use a backup or new test sheet first. Two-way sync applies to mapped editable fields, while derived values are calculated by DropPilot. Each workspace supports one active spreadsheet connection.')+`<div class="grid2 equal"><div class="card"><div class="cardhead"><h2>Connection settings</h2>${tag(S.account.sync_status)}</div><form id="connection-form" class="stack">${sel('Spreadsheet type','type',c.type||'google',cloudMode?[['google','Google Sheets']]:[['google','Google Sheets'],['excel','Microsoft Excel (.xlsx)']])}${field('Spreadsheet URL / local Excel file path','path',c.path,'text','placeholder="Google Sheet URL or C:\\…\\products.xlsx"')}${field('Tab name','tab',c.tab||'Products')}<label class="row"><input type="checkbox" name="auto" ${c.auto!==false?'checked':''}> Enable automatic two-way synchronization</label></form><div class="row" style="margin-top:16px">${btn('Connect / save','connect','link','primary')}${c.type?btn('Disconnect','disconnect','close'):''}</div><div class="hr"></div><div class="summary"><div class="line">Last successful sync <b>${esc(date(S.account.last_sync))}</b></div><div class="line">Automatic interval <b>${S.account.settings.interval}s</b></div><div class="line">Column mapping <b>${S.account.columns.length} fields</b></div></div></div><div class="card"><h2>Setup instructions</h2><div class="hr"></div><h3>Google Sheets</h3><p class="muted">${cloudMode?'Set GOOGLE_SERVICE_ACCOUNT_JSON in Vercel Environment Variables and share the sheet with the service account email as Editor. Create the tab first. Automatic sync runs while this workspace is open.':'Enable Google Sheets API, save your service account key as google-key.json and share your sheet with its email as Editor.'}</p><div class="hr"></div><h3>Microsoft Excel</h3><p class="muted">${cloudMode?'Cloud hosting cannot access files on your PC. Use Google Sheets online or the local version for automatic Excel file sync. CSV import/export remains available.':'Enter an absolute .xlsx file path. Close Excel before app writes to avoid file locks. Saved external changes sync on the next interval.'}</p><div class="hr"></div>${btn('Configure columns','go:builder','sheet')}${btn('Export CSV','export','download','ghost')}</div></div><div class="card"><h2>Synchronization activity</h2>${events(S.events.filter(e=>/sync|spreadsheet/i.test(e.title)).slice(0,8))}</div>`}
function monitor(){let t=stats(),ps=t.p;return head('Product monitoring','Review recorded stock, price changes and profit alerts.',btn('Refresh sheet','sync','sync')+btn('View alerts','go:notifications','bell','primary'))+banner('No authorized live Amazon provider is connected. Monitoring reacts to spreadsheet changes and manual/extension captures. Last checked means the time you actually verified availability; it is not a live marketplace timestamp.')+`<div class="cards">${metric('Tracked products',String(ps.length),'Recorded products','box')}${metric('In stock',String(t.stock),'Last recorded status','check','good')}${metric('Out of stock',String(t.out),'Needs review','alert','bad')}${metric('Unknown',String(t.unknown),'Verify manually','info','warn')}</div><div class="card"><div class="cardhead"><h2>Inventory watchlist</h2></div><div class="tablewrap"><table class="table"><thead><tr><th>Product</th><th>Availability</th><th>Price</th><th>Est. profit</th><th>Health</th><th>Last checked</th><th>Action</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${productCell(p)}</td><td>${tag(p.stock)}</td><td>${money(p.source_price)}</td><td class="${p.profit<S.account.settings.target_profit?'warn':'good'}">${money(p.profit)}</td><td>${p.health}/100</td><td>${esc(p.last_checked||'Never')}</td><td>${btn('Update','edit:'+p.id,'edit','small')}</td></tr>`).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`}
function settingsPage(fees=false){let s=S.account.settings;return head(fees?'Fee & pricing rules':'Workspace settings',fees?'Configure estimated fee schedules and recalculate existing products.':'Manage preferences, sync frequency and local backups.',btn('Save settings','save-settings','check','primary'))+`<div class="grid2 equal"><div class="card"><h2>${fees?'Fee calculator defaults':'General preferences'}</h2><div class="hr"></div><form id="settings-form" class="formgrid">${fees?`${sel('Marketplace','marketplace',s.marketplace,['US','UK','Other'])}${nfield('Final value fee (%)','fee_pct',s)}${nfield('Fixed order fee ($)','fixed_fee',s)}${nfield('Promoted listing fee (%)','ad_pct',s)}${nfield('Target profit ($)','target_profit',s)}${nfield('Competitor undercut ($)','undercut',s)}${nfield('Minimum ROI (%)','min_roi',s)}<label class="span2 row"><input type="checkbox" name="apply_fees"> Apply fee defaults to all existing products</label>`:`${field('Delivery ZIP/postcode','zip',s.zip)}${field('Auto sync interval (seconds)','interval',s.interval,'number','min="15" max="86400" step="1"')}${sel('Appearance','theme',theme,[['light','Light'],['dark','Dark']])}`}</form></div><div class="card"><h2>${fees?'Fee verification':'Local data & workspace'}</h2><div class="hr"></div>${fees?`<p class="muted">Default fees are illustrative and editable, not verified live rates. Review official fee schedules, category tiers and buyer tax before applying a change. No automatic fee scraper is enabled.</p><p><a href="https://www.ebay.com/help/selling/fees/selling-fees?id=4822" target="_blank" rel="noopener noreferrer">Official eBay selling fees ${I('external')}</a></p>`:`<p class="muted">This local demo has no login screen. Workspaces have separate data but are not security boundaries. Do not expose this server to the internet.</p><div class="row">${btn('New workspace','new-account','plus')}${btn('Create database backup','backup','download')}</div><div class="hr"></div><p class="muted">All data is stored in a local SQLite database. The application works offline except Google Sheets sync.</p>`}</div></div>`}
function research(){return head('Competitor research','Track competitor links and compare landed selling prices.',btn('Add product','go:add','plus','primary'))+banner('Competitor data and sold counts are manually verified or imported from your sheet. No eBay account or live API is connected.')+`<div class="card"><h2>Research workspace</h2><div class="hr"></div><div class="tablewrap"><table class="table"><thead><tr><th>Product</th><th>Competitor price</th><th>Your price</th><th>7 days</th><th>14 days</th><th>30 days</th><th></th></tr></thead><tbody>${S.products.map(p=>`<tr><td>${productCell(p)}</td><td>${money(p.competitor_price)}</td><td>${money(p.selling_price)}</td><td>${esc(p.sold7??'—')}</td><td>${esc(p.sold14??'—')}</td><td>${esc(p.sold30??'—')}</td><td>${btn('Compare','competitors:'+p.id,'search','small')}</td></tr>`).join('')||`<tr><td colspan="7">${empty()}</td></tr>`}</tbody></table></div></div>`}
function analytics(){let t=stats(),p=t.p,positive=p.filter(x=>x.profit>0).length,low=p.filter(x=>x.profit<S.account.settings.target_profit).length;return head('Research analytics','Product-level estimates; no actual order revenue is assumed.',btn('Export CSV','export','download'))+`<div class="cards">${metric('Profitable products',String(positive),'Positive estimated profit','chart','good')}${metric('Below target',String(low),'Below '+money(S.account.settings.target_profit)+' per unit','alert','warn')}${metric('Average ROI',pct(t.roi),'Simple average of known ROI','chart')}${metric('Published products',String(t.profits.length),'Ready for spreadsheet sync','sheet')}</div><div class="card"><h2>Profitability ranking</h2><div class="hr"></div>${smallTable([...p].sort((a,b)=>b.profit-a.profit))}</div>`}
function notifications(){return head('Notifications','Your stock, price, sync and product activity.',btn('Mark all read','seen','check'))+`<div class="card">${events(S.events)}</div>`}
function trashPage(){return head('Recycle bin','Restore products without losing their research history.')+banner('Deletion is local and reversible. Linked spreadsheet rows are intentionally retained to avoid destroying company data.')+`<div class="card">${S.trash.map(p=>`<div class="event">${productCell(p)}<span class="spacer"></span>${btn('Restore','restore:'+p.id,'history','small')}</div>`).join('')||empty('Recycle bin is empty','Deleted products will appear here.')}</div>`}
function render(){if(!S)return;document.documentElement.classList.toggle('dark',theme==='dark');let unread=S.events.filter(e=>!e.seen).length;let body=({dashboard,products:productsPage,add:productForm,calculator,builder,sheets:spreadsheets,monitor,research,analytics,notifications,trash:trashPage,fees:()=>settingsPage(true),settings:()=>settingsPage(false)})[page]();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="/favicon.svg" alt=""><div>DropPilot<small>Research workspace</small></div></div>${navs.map(([label,ns])=>`<div class="navlabel">${label}</div>${ns.map(([k,n,i])=>`<button class="nav ${page===k?'active':''}" data-action="go:${k}">${I(i)}${esc(n)}</button>`).join('')}`).join('')}<div class="sidebarfoot"><div><span class="side-dot"></span>${cloudMode?'Cloud workspace':'Local workspace'}</div><div>DropPilot v1.1 · ${S.account.demo?'Demo mode':'Personal mode'}</div></div></aside><main class="main"><header class="topbar">${btn('','menu','menu','ghost mobilemenu icon','aria-label="Open menu"')}<div class="crumb">Workspace / <b>${esc(navname())}</b></div><span class="spacer"></span><span class="syncpill">${I(S.account.sync_status==='Synchronized'?'check':'sync')}${esc(S.account.sync_status)}</span><button class="searchtop" data-action="global-search">${I('search')}<span>Search</span><span class="kbd">Ctrl K</span></button><select class="workspace-select" id="workspace" aria-label="Workspace">${S.accounts.map(a=>`<option value="${a.id}" ${a.id===A?'selected':''}>${esc(a.name)}</option>`).join('')}<option value="new">+ New workspace</option></select>${btn('','theme',theme==='dark'?'sun':'moon','ghost icon','aria-label="Toggle dark mode"')}<div class="bellwrap">${btn('','go:notifications','bell','ghost icon','aria-label="Notifications"')}${unread?`<span class="badge-dot">${Math.min(99,unread)}</span>`:''}</div><button class="avatar" data-action="go:settings" aria-label="Workspace settings">${esc(S.account.name.slice(0,1).toUpperCase())}</button>${authRequired?btn('Sign out','logout','','ghost','aria-label="Sign out"'):''}</header><div class="content">${body}</div></main></div>`;bindInputs()}
function bindInputs(){let s=$('#search-products');if(s)s.oninput=()=>{let pos=s.selectionStart;search=s.value;pg=1;render();$('#search-products').focus();$('#search-products').setSelectionRange(pos,pos)};let f=$('#product-filter');if(f)f.onchange=()=>{filter=f.value;pg=1;render()};let so=$('#product-sort');if(so)so.onchange=()=>{sort=so.value;render()};let w=$('#workspace');if(w)w.onchange=async()=>{if(w.value==='new'){w.value=A;newAccount();return}A=w.value;localStorage.setItem('dp-account',A);page='dashboard';edit=null;formDraft=null;search='';filter='All';await refresh()};$$('[data-select]').forEach(el=>el.onchange=()=>{el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render()});let all=$('#select-page');if(all)all.onchange=()=>{filtered().slice((pg-1)*25,pg*25).forEach(p=>all.checked?selected.add(p.id):selected.delete(p.id));render()};let form=$('#product-form')||$('#calc-form');if(form)form.oninput=()=>{formDraft={...(edit||{}),...getForm(form)};$('#profit-summary').innerHTML=summary(formDraft);if($('#title-count'))$('#title-count').textContent=(formDraft.seo_title||'').length+' / 80 characters'};$$('[data-heading]').forEach(el=>el.oninput=()=>{columns[+el.dataset.heading].heading=el.value;dirtyColumns=true;let h=$$('.sheetpreview th')[+el.dataset.heading];if(h)h.textContent=el.value});$$('[data-source]').forEach(el=>el.onchange=()=>{columns[+el.dataset.source].source=el.value;dirtyColumns=true;render()})}
function newAccount(){modal('Create workspace',field('Workspace name','new-name','','text','placeholder="eBay account 01"'),async()=>{let name=$('#f-new-name').value;let r=await api('accounts',{name});A=r.id;localStorage.setItem('dp-account',A);page='dashboard';await refresh();toast('Workspace created','Your new workspace is empty and independent.')},{label:'Create workspace'})}
function save(status){let form=$('#product-form');if(!form.reportValidity())return;let p=getForm(form);p.status=status==='current'?p.status:status;confirm(status==='Published'?'Publish product?':'Save product?',status==='Published'?'Save the product to this workspace and queue spreadsheet sync. No eBay listing will be created.':'Save changes locally.',async()=>{await api('product',{id:edit?.id,product:p});edit=null;formDraft=null;page='products';await refresh();toast(status==='Published'?'Product published successfully':'Product saved',S.account.connection.type?'Spreadsheet sync queued if enabled.':'Saved locally. Connect a sheet to synchronize.')},false,status==='Published'?'Publish':'Save')}
async function showHistory(id){let h=await api('history?account='+A+'&id='+id);modal('Price & stock history',h.length?`<div class="sheetpreview"><table class="table"><thead><tr><th>Recorded</th><th>Source</th><th>Selling</th><th>Stock</th><th>Profit</th></tr></thead><tbody>${h.map(x=>`<tr><td>${esc(date(x.created))}</td><td>${money(x.body.source_price)}</td><td>${money(x.body.selling_price)}</td><td>${esc(x.body.stock)}</td><td>${money(x.body.profit)}</td></tr>`).join('')}</tbody></table></div>`:empty('No history'),null,{wide:true})}
async function competitors(id){let cs=await api('competitors?account='+A+'&id='+id);let low=cs.length?Math.min(...cs.map(c=>c.total)):null;modal('Competitor comparison',`<p>Lowest recorded total: <b>${money(low)}</b></p><div class="sheetpreview"><table class="table"><thead><tr><th>Listing</th><th>Total</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Open listing ${I('external')}</a></td><td>${money(c.total)}</td><td>${btn('','comp-del:'+id+':'+c.id,'trash','ghost icon')}</td></tr>`).join('')}</tbody></table></div><div class="hr"></div><form id="competitor-form" class="formgrid"><div class="span2">${field('Competitor URL','url','','url','required')}</div>${field('Price ($)','price','','number','required min="0" step=".01"')}${field('Shipping ($)','shipping',0,'number','min="0" step=".01"')}</form>${low!=null?btn('Use lowest price','comp-use:'+id+':'+low,'calc','small'):''}`,async()=>{let f=$('#competitor-form');if(!f.reportValidity())throw Error('Complete the competitor form');await api('competitor',{product:id,entry:getForm(f)});toast('Competitor added');setTimeout(()=>competitors(id),0)},{label:'Add competitor',wide:true})}
async function action(a){let [cmd,arg,arg2]=a.split(':');if(cmd==='logout'){confirm('Sign out?','You will need to enter your credentials again.',logout,false,'Sign out');return}if(cmd==='go'){if(arg==='calculator')formDraft=null;go(arg);return}if(cmd==='menu'){$('.sidebar').classList.toggle('show');return}if(cmd==='theme'){theme=theme==='dark'?'light':'dark';localStorage.setItem('dp-theme',theme);render();return}if(cmd==='new-account'){newAccount();return}if(cmd==='close-modal'){closeModal();return}if(cmd==='confirm'){if(!modalFn||busy)return;busy=true;let b=$('[data-action="confirm"]');if(b)b.disabled=true;try{await modalFn();closeModal()}finally{busy=false;if(b)b.disabled=false}return}if(cmd==='global-search'){go('products');$('#search-products').focus();return}if(cmd==='edit'){edit=S.products.find(p=>p.id===arg);formDraft=null;page='add';render();window.scrollTo(0,0);return}if(cmd==='view'){grid=!grid;render();return}if(cmd==='prev'||cmd==='next'){pg+=cmd==='prev'?-1:1;render();return}if(cmd==='save'){save(arg);return}if(cmd==='history'){await showHistory(arg);return}if(cmd==='delete'||cmd==='bulk'||cmd==='restore'){let ids=cmd==='bulk'?[...selected]:[arg],act=cmd==='bulk'?arg:cmd;confirm(act==='delete'?'Move to recycle bin?':'Update products?',`${ids.length} product(s) will be ${act==='delete'?'removed from the active workspace. Spreadsheet rows are retained.':act==='restore'?'restored.':'updated.'}`,async()=>{await api('bulk',{ids,action:act});selected.clear();await refresh();toast('Products updated successfully')},act==='delete');return}if(cmd==='asin'){let f=$('#product-form'),m=f.elements.amazon_url.value.match(/\/(?:dp|gp\/product)\/([A-Z0-9]{10})(?:[/?#]|$)/i);if(!m)throw Error('No ASIN found in the URL. Use a full Amazon product link.');f.elements.asin.value=m[1].toUpperCase();f.oninput();toast('ASIN extracted','No live price was fetched.','info');return}if(cmd==='optimize'){let f=$('#product-form');f.elements.seo_title.value=optimize(f.elements.title.value);f.oninput();toast('SEO title optimized');return}if(cmd==='checked'){let f=$('#product-form');f.elements.last_checked.value=new Date().toISOString();f.oninput();return}if(cmd==='undercut'||cmd==='calc-undercut'){let f=$('#product-form')||$('#calc-form');f.elements.selling_price.value=Math.max(0,num(f.elements.competitor_price.value)-S.account.settings.undercut).toFixed(2);f.oninput();return}if(cmd==='paste'){let t=await navigator.clipboard.readText();capture(JSON.parse(t));return}if(cmd==='add-column'){let used=new Set(columns.map(c=>c.source)),k=Object.keys(fields).concat(custom.map(f=>f.key)).find(k=>!used.has(k));if(!k)throw Error('All available fields are mapped. Create a custom field.');columns.push({id:uid(),heading:fields[k]||custom.find(f=>f.key===k).heading,source:k});dirtyColumns=true;render();return}if(cmd==='col-up'||cmd==='col-down'||cmd==='col-del'){let i=+arg;if(cmd==='col-del')columns.splice(i,1);else{let j=i+(cmd==='col-up'?-1:1);[columns[i],columns[j]]=[columns[j],columns[i]]}dirtyColumns=true;render();return}if(cmd==='custom-field'){modal('Create a custom column',`<div class="stack">${field('Column heading','custom-name','','text','placeholder="Supplier reference"')}${sel('Data type','custom-type','text',[['text','Text'],['number','Number / price'],['url','Link / URL']])}</div><p>This field will appear on the product editor and in your sheet mapping.</p>`,async()=>{let h=$('#f-custom-name').value.trim();if(!h)throw Error('Enter a heading');let k='custom_'+uid();custom.push({key:k,heading:h,type:$('#f-custom-type').value});columns.push({id:uid(),heading:h,source:k});dirtyColumns=true;render();toast('Custom column added','Save mapping to apply it.')},{label:'Create column'});return}if(cmd==='save-columns'){await api('columns',{columns,custom});dirtyColumns=false;await refresh(false);columns=structuredClone(S.account.columns);custom=structuredClone(S.account.custom);render();toast('Column mapping saved','New columns will be populated on the next sync.');return}if(cmd==='connect'){let f=$('#connection-form'),c=getForm(f);c.auto=f.elements.auto.checked;confirm('Connect spreadsheet?','Use a backup sheet first. The app will add mapped headings and stable row IDs.',async()=>{await api('connect',{connection:c});await refresh();toast('Connection saved','Click Sync now to verify the connection.')},false,'Connect');return}if(cmd==='disconnect'){confirm('Disconnect spreadsheet?','Existing data will be preserved locally and in the spreadsheet.',async()=>{await api('connect',{connection:{}});await refresh();toast('Spreadsheet disconnected')});return}if(cmd==='sync'){if(!S.account.connection.type)throw Error('Connect a spreadsheet first');toast('Synchronizing…','Checking both sides.','info');let r=await api('sync',{});await refresh();toast(r.message,r.conflicts?.length?r.conflicts.slice(0,3).join(' · '):`${r.imported??0} imported / updated; ${r.written??0} cells or rows written`,r.conflicts?.length?'info':'success');return}if(cmd==='save-settings'){let f=$('#settings-form');if(!f.reportValidity())return;let s=getForm(f);await api('settings',{settings:s,apply_fees:!!f.elements.apply_fees?.checked});if(s.theme){theme=s.theme;localStorage.setItem('dp-theme',theme)}await refresh();toast('Settings saved');return}if(cmd==='seen'){await api('seen',{});await refresh();toast('Notifications marked as read');return}if(cmd==='export'){await exportCsv();return}if(cmd==='csv'){modal('Import CSV',`<p>Use matching sheet headers or internal field names. Rows are imported as drafts unless a status is provided.</p><input type="file" id="csv-file" accept=".csv,text/csv">`,async()=>{let f=$('#csv-file').files[0];if(!f)throw Error('Choose a CSV file');let r=await api('import',{csv:await f.text()});await refresh();toast('CSV import complete',`${r.count} imported. ${r.errors.length} rejected. ${r.errors.slice(0,2).join(' · ')}`,r.errors.length?'info':'success')},{label:'Import'});return}if(cmd==='backup'){if(cloudMode){modal('Cloud backup','<p>Export your workspace as CSV or use your PostgreSQL provider backup tools.</p>');return}let r=await api('backup',{});modal('Backup created',`<p>Database backup saved locally:</p><p class="mono">${esc(r.path)}</p>`);return}if(cmd==='competitors'){await competitors(arg);return}if(cmd==='comp-del'){await api('competitor/delete',{id:arg2});await competitors(arg);return}if(cmd==='comp-use'){let price=Number(arg2);await api('product',{id:arg,product:{competitor_price:price,selling_price:Math.max(0,price-S.account.settings.undercut)}});closeModal();await refresh();toast('Pricing updated');return}}
function capture(p){if(!p||typeof p!=='object')throw Error('Invalid extension capture');if(!S) return;edit=null;formDraft={...defaultProduct(),...Object.fromEntries(Object.entries(p).filter(([k])=>['amazon_url','ebay_url','title','source_price','shipping','stock','last_checked','source_seller','delivery','competitor_price','asin'].includes(k)))};page='add';render();toast('Capture imported','Review details before publishing.')}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();try{await action(b.dataset.action)}catch(err){toast('Action could not be completed',err.message,'error')}});document.addEventListener('submit',e=>e.preventDefault());document.addEventListener('keydown',e=>{if(!S)return;if(e.key==='Escape'){closeModal();$('.sidebar')?.classList.remove('show')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();go('products');$('#search-products').focus()}if(e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();go('add')}if(page==='add'&&e.ctrlKey&&e.key==='Enter'){e.preventDefault();save('Published')}});
async function bootWorkspace(){let b=await api('bootstrap');token=b.token;cloudMode=b.cloud;authRequired=b.auth;fields=b.fields;derived=b.derived;A=localStorage.getItem('dp-account');if(!b.accounts.some(a=>a.id===A))A=b.accounts[0].id;await refresh();if(location.hash.startsWith('#capture=')){try{capture(JSON.parse(decodeURIComponent(location.hash.slice(9))))}catch(e){toast('Invalid capture',e.message,'error')}history.replaceState(null,'',location.pathname)}clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(!S||busy||$('#modal-root').children.length||['add','builder','sheets','settings','fees','calculator'].includes(page))return;if(document.activeElement?.matches('input,select,textarea'))return;try{let old=S.events[0]?.id;await refresh(false);if(S.events[0]?.id!==old&&S.events[0]?.kind==='warning')toast(S.events[0].title,S.events[0].detail,'info');render()}catch(e){}},12000);clearInterval(syncTimer);if(cloudMode)syncTimer=setInterval(async()=>{if(!S||busy||!S.account.connection?.auto||S.account.connection.type!=='google')return;try{let r=await api('auto-sync',{});if(!r.skipped&&!r.busy&&!['add','builder','sheets','settings','fees','calculator'].includes(page))await refresh()}catch(e){}},30000)}
async function boot(){let r=await fetch('/api/auth/status',{cache:'no-store'}),v=await r.json();authRequired=v.required;cloudMode=v.cloud;if(authRequired)showLogin(v.configured?'':'Login is not configured. Check deployment settings.');else await bootWorkspace()}
window.addEventListener('pageshow',e=>{if(e.persisted&&authRequired)showLogin()});window.addEventListener('pagehide',()=>{if(authRequired){authToken='';S=null;}});boot().catch(e=>{$('#app').textContent='DropPilot could not start: '+e.message});
